{
"subject": "geometry",
"subtopic": "basics",
"grade": 8,
"difficulty": 3,
"title": "Теорема Мионэ и инверсия",
"text": "Используя инверсию, докажите теорему о касательной окружности к трём данным окружностям (задача Аполлония). Конкретно: найдите все окружности, касающиеся ω₁: x² + y² = 1, ω₂: (x-4)² + y² = 1, ω₃: (x-2)² + (y-2√3)² = 1.",
"answer": "8 окружностей Аполлония",
"solution": "Три окружности равных радиусов r = 1 с центрами O₁(0,0), O₂(4,0), O₃(2,2√3) образуют правильный треугольник со стороной 4.\n\nДля трёх окружностей одинакового радиуса задача упрощается: искомые окружности касаются всех трёх, причём может быть внешнее или внутреннее касание.\n\n8 вариантов (по знаку касания с каждой из 3-х окружностей: +/-).\n\nАналитически: пусть искомая окружность имеет центр (x, y) и радиус ρ.\nУсловия касания:\n(x - 0)² + y² = (ρ ± 1)² ... ε₁ = ±1\n(x - 4)² + y² = (ρ ± 1)² ... ε₂ = ±1\n(x - 2)² + (y - 2√3)² = (ρ ± 1)² ... ε₃ = ±1\n\nПри ε₁ = ε₂ = ε₃ = +1 (внешнее касание со всеми):\nРасстояния от центра до O₁, O₂, O₃ равны ρ+1.\n→ Центр равноудалён от O₁, O₂, O₃ → центр треугольника O₁O₂O₃.\nЦентроид = ((0+4+2)/3, (0+0+2√3)/3) = (2, 2√3/3).\nρ + 1 = расстояние от центроида до O₁ = √(4 + 4/3) = √(16/3) = 4/√3.\nρ = 4/√3 - 1 = (4 - √3)/√3.\n\nПри ε₁ = ε₂ = ε₃ = -1 (охватывающая): ρ - 1 = 4/√3, ρ = 1 + 4/√3.\n\nОстальные 6 вариантов находятся аналогично, давая в сумме 8 решений (некоторые могут совпадать или быть вырожденными).\n\nОтвет: задача Аполлония имеет до 8 решений; при данной конфигурации все 8 существуют.",
"source": "AI",
"source_dataset": "generated",
"id": 8488,
"is_active": true
},
