{
"subject": "geometry",
"subtopic": "basics",
"grade": 9,
"difficulty": 1,
"title": "Изопероиметрическое неравенство для треугольников",
"text": "Докажите изопероиметрическое неравенство для треугольников: среди всех треугольников с заданным периметром максимальной площадью обладает правильный треугольник. Иными словами, для треугольника со сторонами a, b, c и площадью S: 12√3·S ≤ (a+b+c)². Найдите, при каком соотношении сторон достигается равенство.",
"answer": "Равенство при a = b = c (правильный треугольник)",
"solution": "Пусть p = (a+b+c)/2 — полупериметр, S² = p(p-a)(p-b)(p-c) (формула Герона).\n\nНужно доказать: 12√3·S ≤ 4p², т.е. S ≤ p²/√3·... уточним.\n\nИз S = √(p(p-a)(p-b)(p-c)) и неравенства АМ-ГМ:\n(p-a)(p-b)(p-c) ≤ ((p-a+p-b+p-c)/3)³ = (p/3)³ = p³/27.\n\nСледовательно: S² = p·(p-a)(p-b)(p-c) ≤ p·p³/27 = p⁴/27.\n\nS ≤ p²/√27 = p²/(3√3).\n\nПлощадь через периметр L = 2p: S ≤ (L/2)²/(3√3) = L²/(12√3).\n\nПерепишем: 12√3·S ≤ L² = (a+b+c)². ✓\n\nРавенство в АМ-ГМ: при p-a = p-b = p-c, т.е. a = b = c (правильный треугольник).\n\nПроверка: для правильного треугольника со стороной a:\nL = 3a, S = (√3/4)a².\n12√3·S = 12√3·(√3/4)a² = 12·3·a²/4 = 9a².\n(a+b+c)² = 9a². ✓\n\nОтвет: равенство 12√3·S = (a+b+c)² достигается только для правильного треугольника.",
"source": "AI",
"source_dataset": "generated",
"id": 8429,
"is_active": true
},
