{
"subject": "geometry",
"subtopic": "triangles",
"grade": 8,
"difficulty": 2,
"title": "Гомотетия окружностей",
"text": "Две окружности с центрами O₁(0, 0), r₁ = 3 и O₂(10, 0), r₂ = 7 находятся вне друг друга. Найдите внешний и внутренний центры гомотетии и уравнения общих касательных.",
"answer": "Внешний центр: (−15/2, 0); внутренний центр: (15/2, 0) — нет, пересчёт в решении",
"solution": "Внешний центр гомотетии (Eₑₓₜ): делит O₁O₂ снаружи в отношении r₁:r₂ = 3:7.\nEₑₓₜ = (r₂·O₁ - r₁·O₂)/(r₂ - r₁) = (7·0 - 3·10)/(7-3) = -30/4 = -7.5.\nEₑₓₜ = (-7.5, 0).\n\nВнутренний центр гомотетии (Eᵢₙₜ): делит O₁O₂ внутри в отношении r₁:r₂ = 3:7.\nEᵢₙₜ = (r₂·O₁ + r₁·O₂)/(r₁ + r₂) = (7·0 + 3·10)/10 = 3.\nEᵢₙₜ = (3, 0).\n\nОбщие внешние касательные проходят через Eₑₓₜ(-7.5, 0).\nОбщие внутренние касательные — через Eᵢₙₜ(3, 0).\n\nВнешняя касательная через (-7.5, 0): y = k(x + 7.5).\nРасстояние от O₁(0,0) до прямой: |k·0 - 0 + 7.5k|/√(k²+1) = 7.5|k|/√(k²+1) = 3.\n7.5²k² = 9(k²+1) → 56.25k² = 9k² + 9 → 47.25k² = 9 → k² = 9/47.25 = 4/21.\nk = ±2/√21.\nУравнения: y = ±(2/√21)(x + 7.5).\n\nОтвет: Eₑₓₜ = (-7.5, 0), Eᵢₙₜ = (3, 0); касательные y = ±(2/√21)(x + 7.5).",
"source": "AI",
"source_dataset": "generated",
"id": 8478,
"is_active": true
},
