{
"subject": "geometry",
"subtopic": "triangles",
"grade": 9,
"difficulty": 2,
"title": "Геометрия гиперболической плоскости Пуанкаре",
"text": "Модель Пуанкаре: гиперболическая плоскость — открытый единичный диск D={|z|<1}. «Прямые» — диаметры и дуги окружностей, ортогональных |z|=1. Найдите «прямую» через точки z₁=1/2 и z₂=i/2 (дугу окружности, ортогональной |z|=1).",
"answer": "Окружность x²+y²-(4/3)x-(4/3)y+1/3=0... пересчёт в решении",
"solution": "«Прямая» через 1/2 и i/2 — это дуга окружности, ортогональной |z|=1 и проходящей через z₁=0.5+0i и z₂=0+0.5i.\n\nОкружность, ортогональная x²+y²=1, имеет вид: x²+y²+Dx+Ey+F=0, причём:\nОртогональность: r₀² = 1+D²/4+E²/4-F (... формула: для ортогональности к x²+y²=1 нужно c₀² = r² + r₀², т.е. |O₀|² = 1 + r₀², где O₀ — центр искомой).\nИли условие: 2(a·0+b·0) = F+1, где центр (a,b) = (-D/2,-E/2)... аккуратнее:\n\nДве ортогональные окружности: r₁²+r₂² = d².\nДля x²+y²=1 (r₁=1) и нашей (r₂, центр (a,b)): 1+r₂²=a²+b².\nA²+B² = 1+r₂² → r₂² = D²/4+E²/4-F, a=−D/2, b=−E/2.\nD²/4+E²/4 = 1+D²/4+E²/4−F → F=1.\n\nОкружность x²+y²+Dx+Ey+1=0 (F=1).\nЧерез z₁=(1/2,0): 1/4+D/2+1=0 → D=-5/2.\nЧерез z₂=(0,1/2): 1/4+E/2+1=0 → E=-5/2.\n\nОкружность: x²+y²-(5/2)x-(5/2)y+1=0.\n(x-5/4)²+(y-5/4)²=25/16+25/16-1=50/16-16/16=34/16.\nЦентр (5/4, 5/4), радиус √(34)/4.\n\nОртогональность: |O|² = 25/16+25/16=50/16. r²+1 = 34/16+1 = 50/16. ✓\n\nОтвет: «прямая» — дуга окружности x²+y²-(5/2)x-(5/2)y+1=0 внутри единичного диска.",
"source": "AI",
"source_dataset": "generated",
"id": 8546,
"is_active": true
},
