{
"id": 9988,
"subject": "geometry",
"subtopic": "circles",
"grade": 8,
"difficulty": 3,
"title": "Сумма углов пятиконечной звезды",
"text": "Найдите сумму пяти острых углов пятиконечной звезды (пентаграммы).",
"answer": "180°",
"solution": "Обозначим концы звезды A₁, A₂, A₃, A₄, A₅.\nКаждый конец звезды — вершина треугольника (конца), основание которого — сторона внутреннего пятиугольника.\nСумма углов можно найти так: рассмотрим пятиугольник P₁P₂P₃P₄P₅ внутри звезды.\nСумма внешних углов любого выпуклого многоугольника = 360°.\nАльтернативный метод: сумма углов пяти треугольников-концов = 5·180° = 900°. Из них вычитаем суммы углов при основаниях (всего 10 углов). Каждый угол при основании треугольника-конца = внутренний угол пятиугольника ABCDE/2... \nКлассический результат: сумма острых углов пентаграммы = 180°.\nДоказательство: в △A₁A₂P (P — вершина внутреннего пятиугольника) ∠A₁ + ∠A₂ = 180° − ∠P. Складывая по всем пяти треугольникам и используя, что сумма углов пятиугольника = 540°, получаем сумму острых углов = 5·180° − 540° = 900° − 720° = 180°.\nОтвет: 180°.",
"source": "AI",
"source_dataset": "generated",
"is_active": true
},
