{
"subject": "number_theory",
"subtopic": "divisibility",
"grade": 8,
"difficulty": 1,
"title": "Сумма мультипликативной функции",
"text": "Докажи формулу: Σ_{d|n} μ(d)/d = φ(n)/n.",
"answer": "Обе части мультипликативны и совпадают на примарных",
"solution": "На примарных p^k: левая часть Σ_{d|p^k} μ(d)/d = μ(1)/1 + μ(p)/p = 1 - 1/p. Правая: φ(p^k)/p^k = p^(k-1)(p-1)/p^k = (p-1)/p = 1-1/p ✓. Обе функции мультипликативны (как произведения мультипликативных). Так как они совпадают на всех примарных, они совпадают всюду. Поэтому Σ_{d|n} μ(d)/d = φ(n)/n.",
"source": "AI",
"source_dataset": "generated",
"id": 9181,
"is_active": true
},
