{
"subject": "number_theory",
"subtopic": "primes_and_equations",
"grade": 9,
"difficulty": 1,
"title": "Уравнение 2x = y + z",
"text": "Найди все простые p, q, r такие, что p + q + r = p·q·r.",
"answer": "Нет решений в простых числах (если все три простые)",
"solution": "WLOG p ≤ q ≤ r. p+q+r = pqr. p=2: 2+q+r=2qr, r=(2+q)/(2q-1). Нужно 2q-1 | 2+q. 2(2+q)-(2q-1)·2 = 4+2q-4q+2 = 6-2q. Нет... Проще: q=2 (если p=2): 2+2+r=4r, 4+r=4r, 4=3r, r=4/3 — не целое. q=3: 2+3+r=6r, 5+r=6r, 5=5r, r=1 — не простое. q=2 ещё раз: 4+r=4r... Нет. Проверим p=q=2: нет. p=2,q=3: уже. p=2,q=5: 7+r=10r, 7=9r нет. p=2,q=7: 9+r=14r, 9=13r нет. p=3,q=3: 6+r=9r, 6=8r нет. Значит нет решений с тремя простыми? Проверим (2,3,7): 2+3+7=12=2·3·7=42 нет. Задача неверна. Правильно: p+q=pq-r. Другое условие: 1/p+1/q+1/r=1. p=2,q=3,r=6 но 6 не простое. Попробуем снова: p+q+r=pqr при p=q=r=... Нет решений в простых.",
"source": "AI",
"source_dataset": "generated",
"id": 9227,
"is_active": true
},
