{
"subject": "number_theory",
"subtopic": "primes_and_equations",
"grade": 10,
"difficulty": 2,
"title": "Олимпиадная задача",
"text": "На 900 карточках записаны все натуральные числа от 1 до 900. Карточки, на которых записаны квадраты целых чисел, убирают, а оставшиеся перенумеровывают, начиная с 1. Потом операцию удаления квадратов повторяют. Сколько раз придётся повторить эту операцию, чтобы удалить все карточки?",
"answer": "59",
"solution": "Ответ: 59 раз.\nРешение:\nПри первой операции удалится 30 карточек, останется 900 − 30 = 30 ⋅ 29 карточек. Поскольку 30 ⋅ 29 > 29^2, все квадраты, кроме 30^2, остались. При второй операции удалится 29 карточек. Останется 30 ⋅ 29 − 29 = 29^2 карточек. Таким образом, за две операции перешли от числа 30^2 к числу 29^2.\nЗапишем в общем виде: при первой операции удалится n карточек, останется n^2 - n = n(n - 1) > (n − 1)^2, при второй операции удалится n - 1 карточка. Останется n^2 - n - (n - 1) = (n - 1)^2, то есть за две операции всегда переходят от числа n^2 к числу (n - 1)^2. Всего среди чисел от 1 до 900 содержится 30 квадратов, между ними 29 переходов. Чтобы дойти до единственной карточки потребуется 2 ⋅ 29 операций, и ещё одна, чтобы удалить последнюю карточку с номером 1.",
"source": "HuggingFace",
"source_dataset": "unknown",
"id": 5404,
"is_active": true
},
