{
"subject": "number_theory",
"subtopic": "primes_and_equations",
"grade": 11,
"difficulty": 3,
"title": "Диофантово уравнение четвёртой степени",
"text": "Докажи, что уравнение x⁴ + y⁴ = z² не имеет натуральных решений (случай n=4 ВТФ).",
"answer": "Метод бесконечного спуска Ферма",
"solution": "Предположим (x,y,z) — минимальное натуральное решение, НОД(x,y)=1. x²,y²,z образуют пифагорову тройку (x²)²+(y²)²=z². Из теории: x²=m²-n², y²=2mn, z=m²+n², НОД(m,n)=1, m>n. Из y²=2mn и НОД(m,n)=1: m=2s², n=t² (если n нечётное) или m=2s², n=t². Из x²=m²-n²=(m-n)(m+n) с НОД(m-n,m+n)|2: m-n=u², m+n=v² (нечётные квадраты). Тогда m=(u²+v²)/2, n=(v²-u²)/2. n=t²=(v²-u²)/2. Возникает уравнение t²+u²=v²... и из m=s²: s⁴+t⁴=v²/4... Строгий спуск приводит к меньшему решению.",
"source": "AI",
"source_dataset": "generated",
"id": 9263,
"is_active": true
},
