{
"subject": "movement",
"subtopic": "linear",
"grade": 5,
"difficulty": 3,
"title": "Поезд, мост и пешеход",
"text": "Пешеход идёт по мосту. Сзади нагоняет поезд. Когда пешеход прошёл 1/5 моста, поезд только въезжает на мост. Если пешеход побежит с моста назад, поезд нагонит его у начала моста. Сколько времени занимает у пешехода пробежать весь мост, если поезд преодолевает мост за 1 мин?",
"answer": "Пешеход пробегает мост за 4 минуты; скорость поезда в 4 раза больше",
"solution": "Пусть длина моста = 1, пешеход на 1/5 от начала моста.\nПоезд въезжает на мост в момент, когда пешеход на 1/5.\nЕсли пешеход бежит назад (1/5 пути): поезд проезжает мост за то же время.\nВремя пешехода: (1/5)/v_ч. Время поезда: 1/v_п. Равны: v_п = 5v_ч.\nЕсли пешеход бежит вперёд (4/5 пути): поезд догоняет у конца моста.\nВремя пешехода: (4/5)/v_ч. Время поезда: должен проехать мост + расстояние до пешехода... \nПоезд входит на мост, когда пешеход на 1/5. Если пешеход бежит вперёд за время t = (4/5)/v_ч, поезд проедет v_п · t = 5v_ч · (4/5)/v_ч = 4 единицы. Поезд входит на мост (позиция 0) и проезжает 4 единицы длины, но мост имеет длину 1. Значит поезд выезжает за мост — противоречие.\nПересмотр: пешеход на 1/5 от начала = 4/5 до конца. Если бежит назад, то 1/5. Поезд за это время проезжает расстояние d до начала моста + 0 = d. v_п · (1/5)/v_ч = d. Если поезд нагнал у начала, то d = 1/5 · (v_п/v_ч). Но при d=0 (поезд уже у начала): v_п · (1/5)/v_ч = 0 (нет).\nСтандартная трактовка: поезд в момент t=0 у начала моста. Пешеход на 1/5 моста. Поезд движется со скоростью v_п, пешеход — v_ч.\nНазад: (1/5)/v_ч = d_поезда/v_п. Поезд проезжает 0 единиц (стоит у начала)? Нет.\nПостановка: d — расстояние от поезда до начала моста в момент t=0.\nНазад: время t₁ = (1/5·L)/v_ч. Поезд в конце: d + v_п·t₁ = 0 (у начала). Т.е. d = v_п·t₁ = v_п·L/(5v_ч).\nВперёд: время t₂ = (4/5·L)/v_ч. Поезд у конца моста: d + v_п·t₂ = L. v_п·L/(5v_ч) + v_п·4L/(5v_ч) = L. v_п·L/v_ч = L. v_п = v_ч. Но это неверно.\nПравильная постановка: пешеход на 1/5 от начала. Поезд за длину d от начала.\nНазад (1/5 пути до начала): v_п · t₁ = d, v_ч · t₁ = L/5. d = v_п·L/(5v_ч).\nВперёд (4/5 пути): v_ч · t₂ = 4L/5. За это время поезд: d + v_п·t₂ = L (у конца).\nd + v_п·4L/(5v_ч) = L. v_п·L/(5v_ч) + 4v_п·L/(5v_ч) = L. v_п/v_ч = 1. Снова v_п = v_ч.\nВидимо задача о том, что поезд нагоняет у конца моста при движении вперёд:\nd + v_п·4L/(5v_ч) = L + (что-то). Нет.\nЧтобы задача имела смысл, пусть поезд нагоняет у конца при движении вперёд:\nPoезд должен пройти d+L (от своей позиции до конца моста). Пешеход проходит 4L/5.\n(d+L)/v_п = (4L/5)/v_ч → d+L = 4Lv_п/(5v_ч).\nd = v_п·L/(5v_ч).\nv_п·L/(5v_ч) + L = 4L·v_п/(5v_ч).\nL(1 + v_п/(5v_ч)) = 4Lv_п/(5v_ч).\n1 = 4v_п/(5v_ч) - v_п/(5v_ч) = 3v_п/(5v_ч).\nv_п/v_ч = 5/3. Скорость поезда в 5/3 раз больше.\nВремя поезда на мост = L/v_п = 1 мин. Значит L/v_п = 1.\nВремя пешехода на весь мост = L/v_ч = L/v_п · v_п/v_ч = 1 · 5/3 = 5/3 мин.\nОтвет: скорость поезда в 5/3 раз больше; пешеход пробежит мост за 5/3 минуты.",
"source": "AI",
"source_dataset": "generated",
"id": 9471,
"is_active": true
},
