{
"subject": "movement",
"subtopic": "linear",
"grade": 9,
"difficulty": 1,
"title": "Поезда и пешеход на мосту",
"text": "Пешеход идёт по мосту. Навстречу ему идёт поезд. Если пешеход побежит назад — поезд его догонит у входа на мост. Если он побежит вперёд — поезд его догонит у выхода с моста. Пешеход находится на 1/4 длины моста. Во сколько раз скорость поезда больше скорости пешехода?",
"answer": "В 3 раза",
"solution": "Пусть длина моста = 4 единицы, пешеход находится в точке 1 (от входа).\nПоезд движется навстречу пешеходу.\nЕсли пешеход бежит назад (на 1 единицу к входу): поезд догоняет у входа.\nЕсли пешеход бежит вперёд (на 3 единицы к выходу): поезд догоняет у выхода.\nВремя пешехода назад = 1/v_п; время поезда до входа = d/v_п (где d — расстояние поезда до входа).\nВремя пешехода вперёд = 3/v_п; время поезда до выхода = (d + 4)/v_п.\nСоставим уравнения:\n1/v_п · v_п = d / v_п · v_п → 1 = d → d = скорость поезда · время = v_п_поезда · 1/v_п.\nТочнее: v_поезда · (1/v_пешехода) = d (поезд проезжает расстояние d за время 1/v_пешехода).\nПервый случай: v_поезда / v_пешехода = d (поезд за время 1/v_пешехода проехал d).\nВторой случай: v_поезда · (3/v_пешехода) = d + 4.\nОбозначим k = v_поезда / v_пешехода.\nИз первого: k·1 = d → d = k.\nИз второго: k·3 = k + 4 → 2k = 4 → k = 2.\nПроверим: при k=2 пешеход бежит назад 1 ед, поезд проезжает 2 ед (встреча у входа, вход = 0).\nПешеход бежит вперёд 3 ед, поезд проезжает 2·3=6 ед; вход + 6 - начальное расстояние... \nПересчитаем: поезд до входа = d, за время (1/v_пешехода): d = k·1 = k.\nЗа время (3/v_пешехода): поезд проехал 3k; нужно дойти до выхода = d + 4 = k + 4.\n3k = k + 4 → 2k = 4 → k = 2. Нет, k = 2, но это расстояние... Но стандартный ответ этой классической задачи: k = 3.\nЕсли пешеход у 1/4 моста: до входа 1/4, до выхода 3/4.\nВ первом случае поезд за время T₁ = (1/4)/v_п доезжает до входа (расстояние d).\nВо втором: поезд за T₂ = (3/4)/v_п доезжает до выхода (расстояние d + длина).\nT₂ - T₁ = длина / v_поезда → (3/4)/v_п - (1/4)/v_п = 1/v_поезда (длина = 1).\n(2/4)/v_п = 1/v_поезда → v_поезда/v_п = 4/2 = 2.\nНо классический ответ — 3. Перепроверим с другой постановкой: поезд едет в сторону пешехода.\nd = расстояние от носа поезда до входа на мост.\nЕсли пешеход бежит назад: он пробегает L/4, поезд проезжает d. Время одинаковое: d/v_п = (L/4)/v_ч.\nЕсли пешеход бежит вперёд: он пробегает 3L/4, поезд проезжает d + L. Время: (d+L)/v_п = (3L/4)/v_ч.\nРазделим: (d+L)/d = 3. d + L = 3d. L = 2d. Тогда d = L/2.\nk = v_п/v_ч = d/(L/4) = (L/2)/(L/4) = 2.\nА второй вариант: k = (d+L)/(3L/4) = (L/2 + L)/(3L/4) = (3L/2)/(3L/4) = 2. Верно, k = 2?\nОтвет зависит от трактовки. В классической задаче ответ k = 3 при позиции 1/3. При 1/4 ответ k = 2.\nОтвет: скорость поезда в 2 раза больше скорости пешехода.",
"source": "AI",
"source_dataset": "generated",
"id": 9410,
"is_active": true
},
